{"description":"抓取 Telegram 频道公开预览页并抽取 7.4 相关行","command":"$ErrorActionPreference='Continue'
$tmp=Join-Path $env:TEMP 'tg74'; New-Item -ItemType Directory -Force -Path $tmp | Out-Null
$chs=@('vanileaks','ToukoLeaks','hxg_diluc','genshinleaks','GenshinIntel')
$ua='Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36'
foreach($c in $chs){
  $u="http./"
  $p=Join-Path $tmp "tg-$c.html"
  try{
    $r=Invoke-WebRequest -Uri $u -UseBasicParsing -TimeoutSec 30 -MaximumRedirection 5 -Headers @{'User-Agent'=$ua}
    $t=$r.Content
    if($t -is [byte[]]){$t=[Text.Encoding]::UTF8.GetString($t)}
    [IO.File]::WriteAllText($p,$t,[Text.Encoding]::UTF8)
    $hits=([regex]::Matches($t,'7\.4')).Count
    $imgs=([regex]::Matches($t,'http./|telesco\.pe)[^"'' ]+')).Count
    "== $c OK status=$($r.StatusCode) bytes=$($t.Length) '7.4'count=$hits imgcount=$imgs"
    $m=[regex]::Matches($t,'(?s)Обновление 7\.4')
    "   Обновление7.4 matches=$($m.Count)"
  }catch{
    "== $c FAIL: $($_.Exception.Message)"
  }
}"}

