content.arguments:
{"command":"$ErrorActionPreference='Continue'
$more='./'
New-Item -ItemType Directory -Force -Path $more | Out-Null
$ua='Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36'
$arts=@(
 @{k='baff0909';u='http./'},
 @{k='upd74';u='http./'}
)
foreach($a in $arts){
  try{
    $r=Invoke-WebRequest -Uri $a.u -UseBasicParsing -TimeoutSec 40 -Headers @{'User-Agent'=$ua}
    $t=$r.Content; if($t -is [byte[]]){$t=[Text.Encoding]::UTF8.GetString($t)}
    "===== $($a.k) OK len=$($t.Length)"
    $body=[regex]::Match($t,'(?s)<div[^>]*class="[^"]*(entry-content|article-content|post-content)[^"]*"[^>]*>(.*?)</div>\s*<(footer|div class="(post-|entry-)')')
    $seg=if($body.Success){$body.Groups[2].Value}else{$t}
    $txt=[regex]::Replace($seg,'(?s)<(script|style)[^>]*>.*?</\1>',' ')
    $txt=[regex]::Replace($txt,'<[^>]+>',' ')
    $txt=[regex]::Replace($txt,'\s+',' ').Trim()
    "--- TEXT(" + $txt.Length + ") ---"
    if($txt.Length -gt 3500){$txt.Substring(0,3500)}else{$txt}
    "--- IMGS ---"
    foreach($m in [regex]::Matches($seg,'(?i)(?:src|data-src)="([^"]*wp-content/uploads/[^"]+)"')){
      $u2=$m.Groups[1].Value
      if($u2 -notmatch '-\d+x\d+\.(jpg|png|webp)$'){ $u2 }
    } | Select-Object -Unique
  }catch{ "===== $($a.k) FAIL: $($_.Exception.Message)" }
}","description":"抓 wotpack 两篇文章正文与图片地址"}

