$more='./'
New-Item -ItemType Directory -Force -Path $more | Out-Null
$ua='Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36'
$arts=@(
 @{k='baff0909';u='http./'},
 @{k='upd74';u='http./'}
)
$all=@()
foreach($a in $arts){
  try{
    $r=Invoke-WebRequest -Uri $a.u -UseBasicParsing -TimeoutSec 40 -Headers @{'User-Agent'=$ua}
    $t=$r.Content; if($t -is [byte[]]){$t=[Text.Encoding]::UTF8.GetString($t)}
    "===== $($a.k) len=$($t.Length)"
    $txt=[regex]::Replace($t,'(?s)<(script|style)[^>]*>.*?</\1>',' ')
    $txt=[regex]::Replace($txt,'(?s)<[^>]+>',' ')
    $txt=[regex]::Replace($txt,'\s+',' ').Trim()
    "TEXT_LEN=$($txt.Length)"
    $i=$txt.IndexOf('бафф'); if($i -lt 0){$i=0}
    $cut=[Math]::Min(3000,$txt.Length-$i)
    $txt.Substring($i,$cut)
    "--- IMGS ---"
    $ims=[regex]::Matches($t,'(?:src|data-src)="([^"]+wp-content/uploads/2026[^"]+)"') | ForEach-Object { $_.Groups[1].Value } | Where-Object { $_ -notmatch '-\d+x\d+\.(jpg|png|webp)$' } | Select-Object -Unique
    foreach($u in $ims){ "$u"; $all += $u }
  }catch{ "===== $($a.k) FAIL: $($_.Exception.Message)" }
}
"===== DOWNLOAD ====="
$n=0
foreach($u in ($all | Select-Object -Unique)){
  $n++; if($n -gt 6){break}
  $ext=[IO.Path]::GetExtension(($u -split '\?')[0]); if(-not $ext){$ext='.jpg'}
  $f=Join-Path $more ("wotpack-未知-{0:d2}{1}" -f $n,$ext)
  try{
    Invoke-WebRequest -Uri $u -OutFile $f -UseBasicParsing -TimeoutSec 60 -Headers @{'User-Agent'=$ua}
    $b=(Get-Item $f).Length
    $h=(Get-FileHash $f -Algorithm SHA256).Hash.Substring(0,12)
    "OK $f bytes=$b sha256=$h src=$u"
  }catch{ "FAIL $u : $($_.Exception.Message)" }
}","description":"抓 wotpack 两篇正文、抽图并下载"}

