content.arguments:
{"command":"$ErrorActionPreference='Continue'
$more='./'
New-Item -ItemType Directory -Force -Path $more | Out-Null
$ua='Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36'
$arts=@(
 @{k='baff0909';u='http./'},
 @{k='upd74';u='http./'}
)
$dl=@()
foreach($a in $arts){
  try{
    $r=Invoke-WebRequest -Uri $a.u -UseBasicParsing -TimeoutSec 40 -Headers @{'User-Agent'=$ua}
    $t=$r.Content; if($t -is [byte[]]){$t=[Text.Encoding]::UTF8.GetString($t)}
    "===== $($a.k) RAWIMG ====="
    $tags=[regex]::Matches($t,'<img[^>]+>') | ForEach-Object { $_.Value }
    "img_tags=$($tags.Count)"
    $tags | Where-Object { $_ -match '2026/09|2026/11|baff|insayd' } | Select-Object -First 12
    $urls=[regex]::Matches($t,'http./|11)/[A-Za-z0-9_\-\.]+\.(jpg|png|webp)') | ForEach-Object { $_.Value } | Select-Object -Unique
    foreach($u in $urls){ $dl += @{k=$a.k;u=$u} }
  }catch{ "===== $($a.k) FAIL: $($_.Exception.Message)" }
}
"===== CANDIDATES ====="
$dl | ForEach-Object { "$($_.k) $($_.u)" } | Select-Object -Unique
"===== DOWNLOAD ====="
$seen=@{}
foreach($d in $dl){
  $u=$d.u
  if($seen.ContainsKey($u)){continue}; $seen[$u]=1
  if($u -match '-\d+x\d+\.'){continue}
  $ext=[IO.Path]::GetExtension(($u -split '\?')[0])
  $c=($seen.Keys | Measure-Object).Count
  $f=Join-Path $more ("wotpack-{0}-{1:d2}{2}" -f $d.k,$c,$ext)
  try{
    Invoke-WebRequest -Uri $u -OutFile $f -UseBasicParsing -TimeoutSec 60 -Headers @{'User-Agent'=$ua}
    $b=(Get-Item $f).Length
    $h=(Get-FileHash $f -Algorithm SHA256).Hash.Substring(0,12)
    "OK $f bytes=$b sha256=$h"
  }catch{ "FAIL $u : $($_.Exception.Message)" }
}","description":"提取 wotpack 文章内图片标签并下载候选图"}

